/**
 * PR guides (design/11-pr-guide.md, "Service"): one guide per PR diff, read from the store or
 * generated by a job, at most one job per guide key. Job state lives in memory: a server restart
 * loses running jobs and their failures, and such a key reads as `none` until stored.
 */
import type { PrGuide, PrGuideStatus } from "@pi-code/protocol";
import { type GuideStore, guideKey } from "../store/guide-store.ts";
import type { GuideInput } from "./guide-job.ts";

/** A guide key's state: `none` when nothing is stored, running or failed for it. */
export type GuideState = PrGuideStatus | { state: "none" };

/** Generates the guide of `input`'s PR diff; aborting `signal` kills the job. */
export type GuideRunner = (input: GuideInput, signal: AbortSignal) => Promise<PrGuide>;

/** Told of every change of a key's state. */
export type GuideListener = (key: string, state: GuideState) => void;

/** The guide key of `input`'s PR diff. */
export function guideInputKey({ pr, baseSha, headSha, folder }: GuideInput): string {
  return guideKey({ repo: pr.repo, number: pr.number, baseSha, headSha, folder });
}

interface Job {
  controller: AbortController;
  /** False while `ensure` checks the store, before the job is started. */
  running: boolean;
  done: Promise<void>;
  /** True once the job is storing its guide, which `cancel` then leaves to finish. */
  storing: boolean;
}

export class GuideService {
  private readonly store: GuideStore;
  private readonly run: GuideRunner;
  private readonly jobs = new Map<string, Job>();
  /** The last job's error by key, until the next job for it starts. */
  private readonly failures = new Map<string, string>();
  private readonly listeners = new Set<GuideListener>();

  constructor(store: GuideStore, run: GuideRunner) {
    this.store = store;
    this.run = run;
  }

  /**
   * Running → generating; last job failed → failed; stored → ready (or failed); a job still
   * checking the store → generating, as it finds nothing stored either; else none.
   */
  async status(key: string): Promise<GuideState> {
    if (this.jobs.get(key)?.running) return { state: "generating" };
    const error = this.failures.get(key);
    if (error !== undefined) return { state: "failed", error };
    const stored = await this.store.read(key);
    if (stored !== undefined) return stored;
    return this.jobs.has(key) ? { state: "generating" } : { state: "none" };
  }

  /**
   * Starts the job for `input`'s PR diff unless its guide is stored (outdated or not) or a job
   * for it is already running, whose end the returned promise then waits for. Never rejects:
   * failures are the key's state.
   */
  ensure(input: GuideInput): Promise<void> {
    const key = guideInputKey(input);
    return this.jobs.get(key)?.done ?? this.start(key, input, true);
  }

  /** Generates the guide again (Retry), replacing the stored one; a running job is killed. */
  regenerate(input: GuideInput): Promise<void> {
    const key = guideInputKey(input);
    this.jobs.get(key)?.controller.abort();
    return this.start(key, input, false);
  }

  /**
   * Kills the key's running job, if any, discarding its result; listeners are then told the key's
   * state. A job already storing its guide is left to end as usual, so that an `ensure` meanwhile
   * joins it instead of starting another job before the guide is stored.
   */
  cancel(key: string): void {
    const job = this.jobs.get(key);
    if (job === undefined || job.storing) return;
    job.controller.abort();
    this.jobs.delete(key);
    if (!job.running) return;
    void this.status(key).then((state) => {
      if (!this.jobs.has(key)) this.emit(key, state);
    });
  }

  /** Listens to every change; returns the unsubscribe function. */
  subscribe(listener: GuideListener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private start(key: string, input: GuideInput, unlessStored: boolean): Promise<void> {
    const job: Job = {
      controller: new AbortController(),
      running: false,
      done: Promise.resolve(),
      storing: false,
    };
    this.jobs.set(key, job);
    job.done = this.execute(key, input, job, unlessStored);
    return job.done;
  }

  private async execute(
    key: string,
    input: GuideInput,
    job: Job,
    unlessStored: boolean,
  ): Promise<void> {
    // A cancelled or replaced job is no longer the key's.
    const current = () => this.jobs.get(key) === job;
    let outcome: GuideState;
    try {
      // Awaited even without a read, so that `start` has set `job.done` before a listener told
      // of `generating` can join the job.
      if ((await (unlessStored ? this.store.read(key) : undefined)) !== undefined) {
        if (current()) this.jobs.delete(key);
        return;
      }
      if (!current()) return;
      job.running = true;
      this.failures.delete(key);
      this.emit(key, { state: "generating" });
      const guide = await this.run(input, job.controller.signal);
      if (!current()) return;
      job.storing = true;
      await this.store.write(key, guide);
      outcome = { state: "ready", guide };
    } catch (e) {
      if (!current()) return;
      const error = e instanceof Error ? e.message : String(e);
      this.failures.set(key, error);
      outcome = { state: "failed", error };
    }
    if (!current()) return;
    this.jobs.delete(key);
    this.emit(key, outcome);
  }

  private emit(key: string, state: GuideState): void {
    for (const listener of this.listeners) {
      try {
        listener(key, state);
      } catch (e) {
        console.error("[guides] listener failed:", e);
      }
    }
  }
}
